package Collections_Framework;import java.util.*;public class ARRAYLIST {    public static void main(String[] args) {        ArrayList<Integer> arr = new ArrayList<>();        arr.add(10);        arr.add(20);        arr.add(30);        arr.add(40);        arr.add(50);        System.out.println(arr);        System.out.println(arr.get(3));        ArrayList<Integer> arr1 = new ArrayList<>();        arr1.addAll(arr);        System.out.println(arr1);        arr.remove(2);        System.out.println(arr);    }}